    {
      "entity_scope": "the donor",
      "id": "a3",
      "proposition": "the donor has made a Gift Aid declaration that gives the charity permission to claim Gift Aid",
      "source_ids": ["E05"]
    },
    {
      "entity_scope": "the donation",
      "id": "a4",
      "proposition": "the donation is not made through Payroll Giving",
      "source_ids": ["E09"]
    },
    {
      "entity_scope": "the donation",
      "id": "a5",
      "proposition": "the donation is not a payment for goods or services or made because the charity bought goods and services",
      "source_ids": ["E10"]
    },
    {
      "entity_scope": "the donation",
      "id": "a6",
      "proposition": "the donation is not a payment where the donor receives a benefit over a certain limit",
      "source_ids": ["E11"]
    },
    {
      "entity_scope": "the donation",
      "id": "a7",
      "proposition": "the donation is not a payment of shares",
      "source_ids": ["E12"]
    },
    {
      "entity_scope": "the donation",
      "id": "a8",
      "proposition": "the donation is not from a charity card or of vouchers, such as Charities Aid Foundation (CAF) vouchers",
      "source_ids": ["E13"]
    }
  ],
  "decision_target": "eligibility for Gift Aid",
  "decision_unit": "one donation",
  "eligibility_expression": {
    "ref": "a1"
  },
  "limitations": [
    "The donor's tax documentation for the relevant tax year is not available, and the Gift Aid declaration is incomplete.",
    "The policy does not specify how to handle donations where the donor's tax year differs from the donation year or where tax evidence is missing.",
    "The policy does not specify whether a donation made in one tax year can be claimed in another, or how to evaluate tax liability in the absence of a tax document."
  ],
  "scope_issues": [
    "The policy applies to donations from individuals, but does not specify whether non-individual donations (e.g., corporate) or other types of donations are covered."
  ]
}
